@Override public synchronized Object getProperty(String propertyName){
  try {
    Object value=immutableDefaultProperties.get(propertyName);
    if (value != null) {
      return value;
    }
    this.checkConnection();
    this.selectExact.setString(1,propertyName);
    ResultSet q=this.selectExact.executeQuery();
    if (q.next()) {
      value=q.getString(1);
    }
    if (value != null) {
      return value;
    }
    value=defaultProperties.get(propertyName);
    if (value != null) {
      return value;
    }
    return System.getProperty(propertyName);
  } catch (SQLException e) {
    logger.error(e);
    throw new RuntimeException(e);
  } catch (NullPointerException | SecurityException | IllegalArgumentException e) {
    logger.error(e);
    throw new RuntimeException(e);
  }
}
